import json,statistics
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=Path('results/mnist_fewshot_recovery_20261105');rs=json.loads((p/'results.json').read_text());base=json.loads((p/'baselines.json').read_text());methods=['archive_error','fresh_error','prototype_router','head_adapt'];names=dict(archive_error='Saved-route selection by support error',fresh_error='Fresh branch search (no route archive)',prototype_router='Training-prototype route lookup',head_adapt='Classifier-head adaptation');summary=[]
lines=['# Few-shot recovery of previously learned MNIST tasks','', 'Secondary evaluation, not novel-class few-shot learning. Six frozen checkpoints (three training seeds × two task orders), ten support draws per checkpoint and shot count, four shot counts. Support is drawn from the held-out original training validation split; queries are the separate official test set. 240 support collections / 1,200 two-class task episodes. No model weights or traces change, except a separate temporary head in the head-adaptation baseline.','', '## Queries share the support task','', 'Each episode supplies k labels per class for one previously learned digit pair; its queries come from that same pair. Predictions still use all ten logits, without output masking. This is additional task-context information relative to image-only class-incremental inference.','', '| Labels per class | Saved-route error selection | Fresh branch search | Prototype route lookup | Head adaptation |','|---:|---:|---:|---:|---:|']
def stat(shots,setting,method):
 vals=[statistics.mean(r[setting][method]*100 for r in rs if r['shots']==shots and r['seed']==seed) for seed in [101,102,103]]
 return statistics.mean(vals),statistics.stdev(vals)
for setting in ['episode_accuracy','mixed_accuracy']:
 if setting=='mixed_accuracy':lines+=['','## Mixed-task queries, no query task identity','', 'Collect support for all five pairs. Route every query using nearest support task mean in standardized pixel space, then use that context’s recovered route or adapted head. This is one specific weak router, not an upper bound on mixed-task performance.','', '| Labels per class | Saved-route error selection | Fresh branch search | Prototype route lookup | Head adaptation |','|---:|---:|---:|---:|---:|']
 for shots in [1,2,5,10]:
  cells=[]
  for method in methods:
   mean,sd=stat(shots,setting,method);summary.append(dict(setting=setting,shots=shots,method=method,accuracy=mean,seed_sd=sd));cells.append(f'{mean:.2f} ± {sd:.2f}%')
  lines.append('| '+str(shots)+' | '+' | '.join(cells)+' |')
image=statistics.mean(b['image_accuracy'] for b in base)*100;oracle=statistics.mean(b['oracle_accuracy'] for b in base)*100
lines+=['',f'Unadapted image-only baseline: **{image:.2f}%**. Archived-task-ID oracle: **{oracle:.2f}%**. Baseline/oracle use sample-weighted test accuracy; episodic results average the five task accuracies equally.','', '## Interpretation and limits','', '- Fresh branch search uses no archived routes or task prototypes: initialize branch choices from mean absolute support responses and perform two coordinate-descent sweeps minimizing support CE. Only support labels guide choices. Labels are never used to choose a route for an individual query.','- Saved-route error selection chooses among all five archived routes by support CE; route IDs are not directly matched to support class labels.','- Prototype lookup uses five training task means plus archived routes; it uses extra stored summaries. Head adaptation fits a separate ten-class head for twenty fixed Adam steps on support, with frozen image-only soft features.','- The support labels reveal the pair of classes in an episode. All methods receive the same support images and labels. High task-conditioned accuracy does not establish novel-class learning, superiority to ordinary few-shot classifiers, or solved class-incremental learning.','- A plain MLP and other established few-shot baselines were not evaluated here. These comparisons test recovery within the trained branch model.','- Accuracy ± SD aggregates support repeats and orders within each of three training seeds; repeated use of the same query set is not independent test evidence. Adaptation recipes were fixed before seeing query results; the support pool was previously used for model validation, so this is exploratory secondary evaluation.','- Actual fresh route tensors use 168 int64 indices (1,344 bytes) per task; these could be stored as 168 uint8 bytes. Support images are temporary, not replay during original training. Ten-class predictions are unrestricted throughout. Mixed routing additionally stores five support means (15,680 bytes float32).','- Core network state remains 134,074 parameters, 1.593 MB including sparse indices. All checkpoints are asserted unchanged after the full evaluation.']
(p/'REPORT.md').write_text('\n'.join(lines)+'\n');(p/'summary.json').write_text(json.dumps(summary,indent=2))
fig,axes=plt.subplots(1,2,figsize=(12,4.7),sharey=True)
for ax,setting,title in zip(axes,['episode_accuracy','mixed_accuracy'],['Queries share support task','Mixed-task queries: prototype routing']):
 for method in methods:
  vals=[stat(k,setting,method) for k in [1,2,5,10]];ax.errorbar([1,2,5,10],[v[0] for v in vals],yerr=[v[1] for v in vals],marker='o',capsize=3,label=names[method],alpha=.85)
 ax.axhline(image,color='#64748b',linestyle='--',label=f'Image-only baseline ({image:.1f}%)');ax.set_title(title);ax.set_xlabel('Labeled support examples per class');ax.set_xticks([1,2,5,10]);ax.set_ylim(30,102);ax.grid(alpha=.2)
axes[0].set_ylabel('Query accuracy (%)');handles,labels=axes[0].get_legend_handles_labels();fig.legend(handles,labels,loc='lower center',ncol=2,fontsize=9,bbox_to_anchor=(.5,-.01));fig.suptitle('Few-shot recovery of learned tasks — frozen sparse four-branch MLP');fig.tight_layout(rect=(0,.16,1,.94));fig.savefig(p/'fewshot_recovery.png',dpi=180);plt.close(fig)
print('\n'.join(lines[:24]));print('Report and figure saved')
